-- ============================================================================
-- HABITO — synthetic seed data.
--
-- Invented listings used to demonstrate and test the platform. No real
-- property, owner, photograph or availability is represented here. Every row
-- is flagged is_seed = true so it can be told apart from anything a real
-- user creates, and removed in one statement.
--
-- Generated by scripts/generate-seed-sql.mjs — do not edit by hand.
-- ============================================================================

begin;

-- Replaying is safe. Seed rows are cleared first, along with anything that
-- hangs off them: a conversation about a demo listing is itself demo data,
-- and leaving it would block the delete. Real users' own listings, messages
-- and saved spaces are untouched.
delete from messages where conversation_id in (
  select c.id from conversations c join spaces s on s.id = c.space_id where s.is_seed
);
delete from conversations where space_id in (select id from spaces where is_seed);
delete from favorites where space_id in (select id from spaces where is_seed);
delete from bookings where space_id in (select id from spaces where is_seed);
delete from spaces where is_seed;
delete from properties where is_seed;
delete from profiles where is_seed;




commit;

